B.a1g=s(["BFS(graph, start):","  queue = [start]","  visited = {start}","  while queue is not empty:","    node = queue.dequeue()","    for each neighbor of node:","      if neighbor not in visited:","        visited.add(neighbor)","        queue.enqueue(neighbor)"],t.s)
B.R7=new A.eY("bfs","Breadth-First Search","BFS explores all vertices at the current depth before moving to vertices at the next depth level. It uses a queue data structure and is optimal for finding the shortest path in unweighted graphs.","O(V + E)",B.a1g)
B.XI=s(["DFS(graph, start):","  stack = [start]","  visited = {}","  while stack is not empty:","    node = stack.pop()","    if node not in visited:","      visited.add(node)","      for each neighbor of node:","        stack.push(neighbor)"],t.s)
B.R8=new A.eY("dfs","Depth-First Search","DFS explores as far as possible along each branch before backtracking. It uses a stack data structure (or recursion) and is useful for topological sorting, detecting cycles, and solving puzzles.","O(V + E)",B.XI)
B.a05=s(["Dijkstra(grid, start, end):","  dist[start] = 0","  pq = [(0, start)]","  while pq is not empty:","    (d, cell) = pq.extractMin()","    if cell == end:","      return reconstructPath()","    if d > dist[cell]: continue","    for each neighbor of cell:","      cost = d + edgeCost(cell, neighbor)","      if cost < dist[neighbor]:","        dist[neighbor] = cost","        pq.insert((cost, neighbor))"],t.s)
B.R9=new A.eY("dijkstra","Dijkstra's Algorithm","Dijkstra's algorithm finds the shortest path by always expanding the cell with the smallest distance. Diagonal moves cost \u221a2 \u2248 1.41, cardinal moves cost 1.","O((V + E) log V)",B.a05)
B.Xv=s(["A*(graph, start, goal):","  g[start] = 0","  f[start] = h(start, goal)","  open = priority_queue([(f[start], start)])","  while open is not empty:","    current = open.extract_min()","    if current == goal: return path","    for each neighbor of current:","      tentative_g = g[current] + cost(current, neighbor)","      if tentative_g < g[neighbor]:","        g[neighbor] = tentative_g","        f[neighbor] = g[neighbor] + h(neighbor, goal)","        open.insert((f[neighbor], neighbor))"],t.s)
B.Ra=new A.eY("a_star","A* Algorithm","A* is an informed search algorithm that finds the shortest path using heuristics. It combines the actual cost from start (g) with an estimated cost to goal (h) to prioritize which nodes to explore. A* is optimal when the heuristic is admissible.","O(E log V)",B.Xv)
B.a1u=s(["BFS(grid, start, end):","  queue = [start]","  visited = {start}","  parent = {}","  while queue is not empty:","    cell = queue.dequeue()","    if cell == end:","      return reconstructPath(parent)","    for each neighbor of cell:",u.P,"        visited.add(neighbor)","        parent[neighbor] = cell","        queue.enqueue(neighbor)"],t.s)
B.Rb=new A.eY("bfs","Breadth-First Search","BFS explores all cells at the current distance before moving to cells at the next distance level. It guarantees finding the shortest path in an unweighted grid.","O(V + E)",B.a1u)
B.WB=s(["Dijkstra(graph, start):","  dist[start] = 0","  dist[v] = \u221e for all other v","  pq = priority_queue([(0, start)])","  while pq is not empty:","    (d, u) = pq.extract_min()","    for each neighbor v of u:","      if dist[u] + weight(u,v) < dist[v]:","        dist[v] = dist[u] + weight(u,v)","        pq.insert((dist[v], v))"],t.s)
B.Rc=new A.eY("dijkstra","Dijkstra's Algorithm","Dijkstra's algorithm finds the shortest path from a source node to all other nodes in a weighted graph with non-negative edge weights. It uses a priority queue to always process the node with the smallest known distance.","O((V + E) log V)",B.WB)
B.TP=s(["AStar(grid, start, end):","  g[start] = 0","  f[start] = h(start, end)","  openSet = [(f[start], start)]","  while openSet is not empty:","    cell = openSet.extractMin()","    if cell == end:","      return reconstructPath()","    for each neighbor of cell:","      tentative_g = g[cell] + cost(cell, neighbor)","      if tentative_g < g[neighbor]:","        g[neighbor] = tentative_g","        f[neighbor] = g[neighbor] + h(neighbor, end)","        openSet.insert(neighbor)"],t.s)
B.Rd=new A.eY("a_star","A* Search","A* combines Dijkstra with a heuristic to guide the search toward the goal. Uses Euclidean distance as heuristic. Guarantees shortest path with admissible heuristic.","O((V + E) log V)",B.TP)
B.UQ=s(["DFS(grid, start, end):","  stack = [start]","  visited = {start}","  parent = {}","  while stack is not empty:","    cell = stack.pop()","    if cell == end:","      return reconstructPath(parent)","    for each neighbor of cell:",u.P,"        visited.add(neighbor)","        parent[neighbor] = cell","        stack.push(neighbor)"],t.s)
B.Re=new A.eY("dfs","Depth-First Search","DFS explores as far as possible along each branch before backtracking. It does NOT guarantee the shortest path but uses less memory than BFS.","O(V + E)",B.UQ)
