B.Y8=s(["procedure quickSort(A, low, high)","    if low < high then","        pi := partition(A, low, high)","        quickSort(A, low, pi - 1)","        quickSort(A, pi + 1, high)","    end if","end procedure","","procedure partition(A, low, high)","    pivot := A[high]","    i := low - 1","    for j := low to high - 1 do","        if A[j] < pivot then","            i := i + 1","            swap(A[i], A[j])","        end if","    end for","    swap(A[i + 1], A[high])","    return i + 1","end procedure"],t.s)
B.aaw=new A.fL("quick_sort","Quick Sort","Quick Sort is a divide-and-conquer algorithm that selects a pivot element and partitions the array around it. Elements smaller than the pivot go to the left, and elements larger go to the right.","O(n log n)","O(n log n)","O(n\xb2)","O(log n)",B.Y8)
B.W0=s(["procedure bubbleSort(A: list)","    n := length(A)","    repeat","        swapped := false","        for i := 1 to n-1 do","            if A[i-1] > A[i] then","                swap(A[i-1], A[i])","                swapped := true","            end if","        end for","        n := n - 1","    until not swapped","end procedure"],t.s)
B.aax=new A.fL("bubble_sort","Bubble Sort","Bubble Sort repeatedly steps through the list, compares adjacent elements, and swaps them if they are in the wrong order. The pass through the list is repeated until the list is sorted.","O(n)","O(n\xb2)","O(n\xb2)","O(1)",B.W0)
B.a0m=s(["procedure insertionSort(A)","    for i := 1 to length(A) - 1 do","        key := A[i]","        j := i - 1","        while j >= 0 and A[j] > key do","            A[j + 1] := A[j]","            j := j - 1","        end while","        A[j + 1] := key","    end for","end procedure"],t.s)
B.aay=new A.fL("insertion_sort","Insertion Sort","Insertion Sort builds the sorted array one element at a time by repeatedly picking the next element and inserting it into its correct position.","O(n)","O(n\xb2)","O(n\xb2)","O(1)",B.a0m)
B.VR=s(["procedure heapSort(A)","    buildMaxHeap(A)","    for i := length(A) - 1 down to 1 do","        swap(A[0], A[i])","        heapify(A, 0, i)","    end for","end procedure","","procedure heapify(A, i, n)","    largest := i","    left := 2*i + 1","    right := 2*i + 2","    if left < n and A[left] > A[largest] then","        largest := left","    if right < n and A[right] > A[largest] then","        largest := right","    if largest != i then","        swap(A[i], A[largest])","        heapify(A, largest, n)","end procedure"],t.s)
B.aaz=new A.fL("heap_sort","Heap Sort","Heap Sort uses a binary heap data structure. It first builds a max-heap, then repeatedly extracts the maximum element and places it at the end.","O(n log n)","O(n log n)","O(n log n)","O(1)",B.VR)
B.a1K=s(["procedure mergeSort(A, left, right)","    if left < right then","        mid := (left + right) / 2","        mergeSort(A, left, mid)","        mergeSort(A, mid + 1, right)","        merge(A, left, mid, right)","    end if","end procedure","","procedure merge(A, left, mid, right)","    create temp arrays L and R","    copy A[left..mid] to L","    copy A[mid+1..right] to R","    merge L and R back into A","end procedure"],t.s)
B.aaA=new A.fL("merge_sort","Merge Sort","Merge Sort is a divide-and-conquer algorithm that divides the array into two halves, recursively sorts them, and then merges the sorted halves.","O(n log n)","O(n log n)","O(n log n)","O(n)",B.a1K)
B.Xk=s(["procedure selectionSort(A)","    for i := 0 to length(A) - 2 do","        minIndex := i","        for j := i + 1 to length(A) - 1 do","            if A[j] < A[minIndex] then","                minIndex := j","            end if","        end for","        swap(A[i], A[minIndex])","    end for","end procedure"],t.s)
